import type { OfficialResponseLabel } from '../response-labels';
import type { ImplementationDifficulty, TargetPeriod } from './types';

export interface AuthoritativeQuestionMapping {
  questionCode: string;
  prompt: string;
  domainCode: string;
  isCritical: boolean;
  isHardGate: boolean;
}

export interface QuestionControlPlaybook {
  questionCode: string;
  domainCode: string;
  controlObjective: string;
  expectedStandard: string;
  fraudMechanism: string;
  currentStateDiagnosis: (label: OfficialResponseLabel) => string;
  recommendedControlDesign: string;
  executiveAccountability: string;
  processOwnership: string;
  oversightFunction: string;
  supportingFunctions: string[];
  operatingFrequency: string;
  evidenceRequired: string[];
  minimumAcceptableEvidenceCharacteristics: string[];
  dependencies: string[];
  implementationDifficulty: ImplementationDifficulty;
  targetPeriod: TargetPeriod;
  effectivenessMeasure: string;
  escalationThreshold: string;
  relatedScenarioTypes: string[];
}

function diagnosis(control: string) {
  return (label: OfficialResponseLabel) =>
    // operationalMeaning is authored as a complete sentence, so interpolating it before "; normalised
    // score" produced ".;" in the rendered report. Strip its terminator at the join, once, rather
    // than rewriting the source strings or cleaning up after concatenation.
    `${control} was self-assessed as "${label.label}" (${label.operationalMeaning.replace(/[\s.;,]+$/, '')}; normalised score ${label.normalisedScore}/100). This is self-reported and requires the listed operating evidence before it can be treated as verified.`;
}

