    operatingFrequency: 'Register maintained continuously; formal reassessment at least annually', evidenceRequired: ['Enterprise risk register extract showing the fraud entry', 'Inherent and residual ratings with written rationale', 'Approved fraud risk-appetite statement', 'Minutes recording register review'],
    minimumAcceptableEvidenceCharacteristics: ['Fraud is a discrete entry, not folded into general operational risk', 'Shows owner, rating basis and linked controls', 'Rating changes carry written justification'], dependencies: ['Existing enterprise risk register', 'Named fraud-risk executive'], implementationDifficulty: 'Low', targetPeriod: '30 days',
    effectivenessMeasure: 'Fraud risk carries a current owner, rating and review date in every governing-body risk pack.', escalationThreshold: 'Fraud absent from the register, or a residual rating unreviewed beyond its scheduled date.', relatedScenarioTypes: ['governance_accountability_failure']
