    executiveAccountability: 'CFO / COO', processOwnership: 'Head of Risk with named process owners', oversightFunction: 'Risk Committee / Internal Audit', supportingFunctions: ['Finance', 'Procurement', 'Warehouse and Logistics', 'Customer Operations'],
    operatingFrequency: 'Refreshed with the fraud risk assessment and on material process change', evidenceRequired: ['Process inventory identifying material value-bearing processes', 'Per-process fraud scenario map', 'Control linkage showing preventive and detective controls', 'Process-owner sign-off'],
    minimumAcceptableEvidenceCharacteristics: ['Names specific processes rather than functions', 'Identifies the roles and permissions able to execute each scenario', 'Signed by the accountable process owner'], dependencies: ['Fraud risk assessment method', 'Documented process inventory'], implementationDifficulty: 'Moderate', targetPeriod: '90 days',
    effectivenessMeasure: '100% of material value-bearing processes have a signed fraud map with named controls and residual gaps.', escalationThreshold: 'Any material process unmapped, or a mapped residual gap with no owner.', relatedScenarioTypes: ['risk_blind_spot', 'transaction_anomaly']
