    operatingFrequency: 'On every qualifying change, before implementation', evidenceRequired: ['Change process documentation showing the fraud gate and triggers', 'Completed fraud reviews for recent qualifying changes', 'Accept or remediate decisions', 'Evidence the gate blocked or released go-live'],
