    effectivenessMeasure: 'Every live digital channel carries a current fraud assessment with mapped controls and owned residual gaps.', escalationThreshold: 'A live channel with no assessment, or a channel launched or materially changed without refresh.', relatedScenarioTypes: ['digital_transaction_abuse', 'account_takeover']
