    operatingFrequency: 'Scheduled rule execution at least monthly; monthly tuning review', evidenceRequired: ['Rule and data-check catalogue with scenario linkage', 'Execution logs and results', 'Source reconciliation evidence', 'Monthly tuning record with true/false positive outcomes'],
